    return (f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="{bg}" style="margin:0 0 14px 0;"><tr><td bgcolor="{bg}" style="background-color:{bg};{extra}padding:16px 18px;">{lab}'
     f'<p style="margin:0 0 6px 0;{F}font-size:17px;line-height:1.35;font-weight:bold;color:{C};"><a href="{e(l)}" style="color:{C};text-decoration:none;">{e(t)}</a></p>'
     f'<p style="margin:0 0 8px 0;{F}font-size:14px;line-height:1.6;color:#222222;">{e(r)}</p>'
     f'<p style="margin:0 0 8px 0;{F}font-size:14px;line-height:1.6;color:#222222;"><b>Por que importa:</b> {e(p)}</p>'
     f'<p style="margin:0;{F}font-size:12px;line-height:1.5;color:#666666;">{e(v)} · {d} · <a href="{e(l)}" style="color:{C};">Ler a matéria</a></p></td></tr></table>\n')
